#!/usr/bin/env node
/**
 * ============================================================
 *  Render the REAL superadmin PHP pages with a mock database
 * ============================================================
 *  PHP cannot be installed in this sandbox, but a WebAssembly PHP
 *  8.2 build (npm: php-cli, from WordPress Playground) runs here.
 *  This script uses it to execute the actual templates so the
 *  preview is generated by the shipped code rather than a
 *  hand-written copy.
 *
 *      node tools/render-php-preview.js
 *
 *  What it does:
 *    1. copies the app into .preview-build/
 *    2. swaps config/database.php for tools/php/mock-db.php
 *    3. runs each superadmin page through WASM PHP with
 *       tools/php/bootstrap.php auto-prepended
 *    4. writes the HTML into .preview/superadmin/ plus the shared
 *       assets, and reports warnings / unmatched SQL
 *
 *  If the WASM runtime is unavailable, fall back to
 *  `node tools/build-preview.js` (hand-built static mirror).
 * ============================================================ */

'use strict';

const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const ROOT = path.resolve(__dirname, '..');
const BUILD = path.join(ROOT, '.preview-build');
const OUT = path.join(ROOT, '.preview');

const PHP_CLI_CANDIDATES = [
    process.env.PHP_CLI,
    path.join(ROOT, '..', '.pvtest', 'node_modules', 'php-cli', 'php-cli.js'),
    '/home/user/.pvtest/node_modules/php-cli/php-cli.js',
    path.join(ROOT, 'node_modules', 'php-cli', 'php-cli.js'),
].filter(Boolean);

const SQL_LOG = path.join(require('os').tmpdir(), 'sa-sql-' + process.pid + '.log');

const PHP_CLI = PHP_CLI_CANDIDATES.find(
    (p) => fs.existsSync(p) && fs.existsSync(path.join(path.dirname(p), 'php-8.2.node.js'))
);

if (!PHP_CLI) {
    console.error('WASM PHP runtime not found. Install it with:');
    console.error('  npm install php-cli   (in any directory)');
    console.error('or fall back to: node tools/build-preview.js');
    process.exit(2);
}

/* Pages to render: [script, output name, extra query string] */
const PAGES = [
    ['superadmin/index.php', 'index.html', ''],
    ['superadmin/tenants.php', 'tenants.html', ''],
    ['superadmin/subscriptions.php', 'subscriptions.html', ''],
    ['superadmin/plans.php', 'plans.html', ''],
    ['superadmin/analytics.php', 'analytics.html', '?months=12'],
    ['superadmin/quote_requests.php', 'quote_requests.html', '?id=9'],
    ['superadmin/tenant_details.php', 'tenant_details.html', '?id=18'],
    ['superadmin/settings.php', 'settings.html', ''],
    ['superadmin/login.php', 'login.html', '', { anonymous: true }],

    /* Edge cases — checked but not written into the preview */
    ['superadmin/tenant_details.php', null, '?id=999999', { allowRedirect: true, probe: 'nonexistent tenant redirects' }],
    ['superadmin/tenant_details.php', null, '?id=12', { probe: 'tenant with no companies or ratings' }],
    ['superadmin/analytics.php', null, '?months=6', { probe: 'analytics over 6 months' }],
    ['superadmin/analytics.php', null, '?months=24', { probe: 'analytics over 24 months' }],
    ['superadmin/quote_requests.php', null, '?status=converted', { probe: 'quote pipeline filtered to converted' }],
    ['superadmin/tenants.php', null, '?status=cancelled', { probe: 'tenants filtered to cancelled' }],
];

function copyDir(src, dest) {
    fs.mkdirSync(dest, { recursive: true });
    for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
        const s = path.join(src, entry.name);
        const d = path.join(dest, entry.name);
        if (entry.name === '.git' || entry.name === '.preview' || entry.name === '.preview-build') continue;
        if (entry.isDirectory()) copyDir(s, d);
        else fs.copyFileSync(s, d);
    }
}

function prepareBuild() {
    fs.rmSync(BUILD, { recursive: true, force: true });
    fs.rmSync(OUT, { recursive: true, force: true });
    copyDir(ROOT, BUILD);

    // Swap in the mock connection
    fs.copyFileSync(path.join(ROOT, 'tools', 'php', 'mock-db.php'), path.join(BUILD, 'config', 'database.php'));
    fs.mkdirSync(path.join(BUILD, 'config'), { recursive: true });
}

/* Write-path cases.
   [label, script, POST body, expected write SQL | null, options]
   options: html  — regex the response body must match
            blank — the handler must redirect without rendering
            anonymous / badCsrf — passed through to the bootstrap          */
const POSTS = [
    ['tenants · create', 'superadmin/tenants.php', 'action=create&company_name=Test Tenant&email=test@example.com&phone=123&plan_id=2&subscription_status=trial&trial_months=1&password=Welcome123', /^INSERT INTO tenants/i],
    ['tenants · edit', 'superadmin/tenants.php', 'action=edit&tenant_id=17&company_name=Harmattan Foods Ltd&email=accounts@harmattanfoods.gh&phone=123&plan_id=3&subscription_price=199.99&subscription_status=active&subscription_start_date=2026-08-11&subscription_end_date=2027-08-11&auto_renew=1', /^UPDATE tenants/i],
    ['tenants · status', 'superadmin/tenants.php', 'action=update_status&tenant_id=9&status=active', /^UPDATE tenants/i],
    ['tenants · reset password', 'superadmin/tenants.php', 'action=reset_password&tenant_id=9&password=NewPass123', /^UPDATE tenants/i],
    ['tenants · delete', 'superadmin/tenants.php', 'action=delete&tenant_id=5', /^DELETE FROM tenants/i],
    ['plans · create', 'superadmin/plans.php', 'action=create&plan_name=Scale&price=399.99&max_ratings=5000&max_customers=250&features=Everything&status=active', /^INSERT INTO subscription_plans/i],
    ['plans · edit', 'superadmin/plans.php', 'action=edit&plan_id=1&plan_name=Starter Plus&price=39.99&max_ratings=250&max_customers=20&features=More&status=active', /^UPDATE subscription_plans/i],
    ['plans · toggle', 'superadmin/plans.php', 'action=toggle_status&plan_id=3&status=inactive', /^UPDATE subscription_plans/i],
    ['plans · delete (unused)', 'superadmin/plans.php', 'action=delete&plan_id=9', /^DELETE FROM subscription_plans/i],
    ['plans · delete (in use blocked)', 'superadmin/plans.php', 'action=delete&plan_id=1', null],
    ['subscriptions · extend', 'superadmin/subscriptions.php', 'action=extend&tenant_id=14&extend_months=3', /^UPDATE tenants/i],
    ['subscriptions · status', 'superadmin/subscriptions.php', 'action=update_status&tenant_id=12&status=active', /^UPDATE tenants/i],
    ['subscriptions · auto renew', 'superadmin/subscriptions.php', 'action=auto_renew&tenant_id=12&auto_renew=1', /^UPDATE tenants/i],
    ['tenant details · extend', 'superadmin/tenant_details.php', 'id=18&action=extend&tenant_id=18&extend_months=2', /^UPDATE tenants/i],
    ['tenant details · auto renew', 'superadmin/tenant_details.php', 'id=18&action=auto_renew&tenant_id=18&auto_renew=1', /^UPDATE tenants/i],
    ['quotes · status', 'superadmin/quote_requests.php', 'action=update_status&quote_id=8&status=contacted', /^UPDATE quote_requests/i],
    ['quotes · convert', 'superadmin/quote_requests.php', 'action=convert&quote_id=9&company_name=Bolgatanga Grain Traders&email=amina@bolgagrains.gh&phone=123&plan_id=2&months=12&password=Welcome123&subscription_status=trial', /^INSERT INTO tenants/i],
    ['quotes · delete', 'superadmin/quote_requests.php', 'action=delete&quote_id=4', /^DELETE FROM quote_requests/i],
    ['settings · save', 'superadmin/settings.php', 'action=save_settings&site_name=Optibiz Platform&admin_email=admin@optibiz.com&support_email=support@optibiz.com&currency_symbol=$&ratings_per_page=12&trial_days=30', /^(UPDATE settings|INSERT INTO settings)/i],
    ['settings · admin profile', 'superadmin/settings.php', 'action=save_admin&username=superadmin&email=superadmin@optibiz.com', /^UPDATE super_admins/i],
    ['settings · password', 'superadmin/settings.php', 'action=change_password&current_password=superadmin123&new_password=Sup3rSecret!&confirm_password=Sup3rSecret!', /^UPDATE super_admins/i],
    ['settings · bad password rejected', 'superadmin/settings.php', 'action=change_password&current_password=wrong&new_password=Sup3rSecret!&confirm_password=Sup3rSecret!', null],
    ['csrf · forged token rejected', 'superadmin/tenants.php', 'action=delete&tenant_id=5', null, { badCsrf: true }],
    ['login · valid credentials', 'superadmin/login.php', 'username=superadmin&password=superadmin123', null, { anonymous: true, blank: true }],
    ['login · wrong password', 'superadmin/login.php', 'username=superadmin&password=nope', null, { anonymous: true, html: /Invalid username or password/ }],
];

function readSqlLog() {
    if (!fs.existsSync(SQL_LOG)) return [];
    const lines = fs.readFileSync(SQL_LOG, 'utf8').split('\n').filter(Boolean);
    fs.unlinkSync(SQL_LOG);
    return lines;
}

function runPhp(script, queryString, opts) {
    const args = [
        PHP_CLI,
        '-d',
        'auto_prepend_file=' + path.join(ROOT, 'tools', 'php', 'bootstrap.php'),
        '-d',
        'error_reporting=E_ALL',
        path.join(BUILD, script),
    ];
    const env = Object.assign({}, process.env, {
        QUERY_STRING: queryString.replace(/^\?/, ''),
        REQUEST_URI: '/' + script + queryString,
        SCRIPT_NAME: '/' + script,
        SA_SQL_LOG: SQL_LOG,
        SA_ANONYMOUS: opts && opts.anonymous ? '1' : '',
        SA_POST: opts && opts.post ? '1' : '',
        SA_BAD_CSRF: opts && opts.badCsrf ? '1' : '',
        SA_EMPTY_DB: opts && opts.emptyDb ? '1' : '',
    });
    try {
        const out = execFileSync('node', args, {
            cwd: BUILD,
            env,
            encoding: 'utf8',
            maxBuffer: 64 * 1024 * 1024,
            timeout: 180000,
        });
        return { html: out, stderr: '' };
    } catch (e) {
        return { html: e.stdout || '', stderr: e.stderr || String(e.message || e) };
    }
}

function rewritePaths(html) {
    // The pages emit "../assets/..." which is correct for the preview tree too
    return html;
}

function main() {
    prepareBuild();
    fs.mkdirSync(path.join(OUT, 'superadmin'), { recursive: true });
    copyDir(path.join(ROOT, 'assets'), path.join(OUT, 'assets'));

    let failures = 0;
    const report = [];

    for (const [script, outFile, qs, opts] of PAGES) {
        if (fs.existsSync(SQL_LOG)) fs.unlinkSync(SQL_LOG);
        const options = opts || {};
        const { html, stderr } = runPhp(script, qs, options);
        const sqlLog = readSqlLog();
        const unmatchedSql = sqlLog.filter((l) => l.startsWith('unmatched\t')).map((l) => l.slice(10));
        const problems = [];

        if (!html || html.length < 400) problems.push('empty output (' + html.length + ' bytes)');
        if (/Fatal error|Parse error|Uncaught/.test(html)) problems.push('PHP fatal error in output');

        const warnings = [];
        const combined = html + '\n' + stderr;
        const re = /(Warning|Notice|Deprecated|Fatal error|Parse error):[^<\n]*/g;
        let m;
        while ((m = re.exec(combined)) !== null) warnings.push(m[0].trim().slice(0, 200));
        if (/PHP Stack trace/.test(combined)) {
            warnings.push('stack trace emitted');
        }

        // Any raw PHP left in the page means output buffering went wrong
        if (/<\?php|<\?=/.test(html)) problems.push('raw PHP tags in output');

        const unmatched = [...new Set(unmatchedSql)];
        if (unmatched.length) problems.push(unmatched.length + ' SQL statement(s) not covered by the mock');

        let cleaned = rewritePaths(html);
        // Strip PHP diagnostics that were echoed before/inside the markup
        cleaned = cleaned.replace(/<br \/>\s*\n?<b>(Warning|Notice|Deprecated)<\/b>:[^<]*(<br \/>)?/g, '');
        cleaned = cleaned.replace(/^(Warning|Notice|Deprecated):[^\n]*\n/gm, '');

        if (options.probe) {
            const redirected = html.length === 0;
            const fatal = /Fatal error|Parse error|Uncaught/.test(html + stderr);
            const warns = [...new Set((html + stderr).match(/(Warning|Notice|Deprecated):[^<\n]{0,110}/g) || [])];
            let ok = !fatal && warns.length === 0;
            if (options.allowRedirect) ok = ok && redirected;
            else ok = ok && !redirected && html.length > 4000;
            if (!ok) failures++;
            const label = script.replace('superadmin/', '') + ' ' + qs;
            console.log(
                `  [${ok ? ' ok ' : 'FAIL'}] ${label.padEnd(40)} ${options.probe}` +
                    (fatal ? '  fatal error' : '') +
                    (warns.length ? '  ' + warns[0].trim() : '') +
                    (!ok && !fatal && !warns.length ? redirected ? '  redirected instead of rendering' : '  output too small' : '')
            );
            continue;
        }

        let dest;
        if (script === 'superadmin/login.php') {
            // Serve the login screen at both URLs the app uses
            dest = path.join(OUT, 'login.html');
            fs.mkdirSync(path.join(OUT, 'superadmin'), { recursive: true });
            fs.writeFileSync(path.join(OUT, 'superadmin', 'login.html'), cleaned, 'utf8');
        } else {
            dest = path.join(OUT, 'superadmin', outFile);
        }
        fs.writeFileSync(dest, cleaned, 'utf8');

        if (problems.length) failures++;
        report.push({ script, outFile, bytes: cleaned.length, problems, warnings: [...new Set(warnings)].slice(0, 12), unmatched });
        const flag = problems.length ? 'FAIL' : warnings.length || unmatched.length ? 'warn' : ' ok ';
        console.log(`  [${flag}] ${script.padEnd(34)} ${String(cleaned.length).padStart(7)} bytes  ${[...new Set(warnings)].slice(0, 2).join(' | ')}`);
    }

    /* ---------- write paths ---------- */
    console.log('\nWrite paths (POST handlers):');
    for (const [label, script, body, expect, opts] of POSTS) {
        const o = opts || {};
        if (fs.existsSync(SQL_LOG)) fs.unlinkSync(SQL_LOG);
        const { html, stderr } = runPhp(script, '?' + body, {
            post: true,
            badCsrf: !!o.badCsrf,
            anonymous: !!o.anonymous,
        });
        const writes = readSqlLog()
            .filter((l) => l.startsWith('write\t'))
            .map((l) => l.slice(6));
        const notes = [];
        const fatal = /Fatal error|Parse error|Uncaught/.test(html + stderr);
        if (fatal) notes.push('fatal error');
        if (/(Warning|Notice|Deprecated):/.test(html + stderr)) notes.push('php warnings');

        let ok = !fatal;
        if (expect) {
            if (!writes.some((w) => expect.test(w))) {
                ok = false;
                notes.push(writes.length ? 'unexpected write: ' + writes[0] : 'no write issued');
            }
        } else if (writes.length) {
            ok = false;
            notes.push('wrote when it should not have: ' + writes[0]);
        }
        if (o.html && !o.html.test(html)) {
            ok = false;
            notes.push('expected message not rendered');
        }
        if (o.blank && /<html|auth-form/.test(html)) {
            ok = false;
            notes.push('rendered a page instead of redirecting');
        }

        if (!ok) failures++;
        console.log(
            `  [${ok ? ' ok ' : 'FAIL'}] ${label.padEnd(32)} ${String(writes.length).padStart(2)} write(s)` +
                (notes.length ? '  ' + notes.join(', ') : '')
        );
    }

    /* ---------- fresh install: empty database ---------- */
    console.log('\nEmpty database (fresh install, schema present but no rows):');
    for (const [script, outFile, qs, opts] of PAGES) {
        if (script === 'superadmin/login.php' || (opts && opts.probe)) continue;
        if (fs.existsSync(SQL_LOG)) fs.unlinkSync(SQL_LOG);
        const { html, stderr } = runPhp(script, qs, { emptyDb: true });
        const mayRedirect = script === 'superadmin/tenant_details.php';
        const notes = [];
        const fatal = /Fatal error|Parse error|Uncaught/.test(html + stderr);
        if (fatal) notes.push('fatal error');
        const warns = [...new Set((html + stderr).match(/(Warning|Notice|Deprecated):[^<\n]{0,110}/g) || [])];
        if (warns.length) notes.push(warns.length + ' warning(s): ' + warns[0].trim());
        if (/<\?php|<\?=/.test(html)) notes.push('raw PHP leaked');
        if (html.length < 4000 && !(mayRedirect && html.length === 0)) {
            notes.push('suspiciously small output (' + html.length + 'B)');
        }
        const ok = !fatal && warns.length === 0 && !/<\?php/.test(html) &&
            (html.length >= 4000 || (mayRedirect && html.length === 0));
        if (!ok) failures++;
        console.log(`  [${ok ? ' ok ' : 'FAIL'}] ${script.padEnd(34)} ${String(html.length).padStart(7)} bytes` + (notes.length ? '  ' + notes.join(' | ') : ''));
    }

    /* ---------- access control ---------- */
    console.log('\nAccess control (signed out, every screen must redirect):');
    for (const [script, outFile, qs, opts] of PAGES) {
        if (script === 'superadmin/login.php' || (opts && opts.probe)) continue;
        if (fs.existsSync(SQL_LOG)) fs.unlinkSync(SQL_LOG);
        const { html, stderr } = runPhp(script, qs, { anonymous: true });
        const leaked = /sa-app|sa-sidebar|<!DOCTYPE/i.test(html);
        const fatal = /Fatal error|Parse error|Uncaught/.test(html + stderr);
        const ok = !leaked && !fatal && html.length === 0;
        if (!ok) failures++;
        console.log(`  [${ok ? ' ok ' : 'FAIL'}] ${script.padEnd(34)} ${leaked ? 'rendered content to a signed-out visitor' : fatal ? 'fatal error' : 'redirected with no output'}`);
    }

    // Preview landing page (links use .php URLs, the server rewrites them)
    fs.writeFileSync(path.join(OUT, 'index.html'), previewIndex(report), 'utf8');
    console.log('  [ ok ] index.html (preview landing page)');

    fs.rmSync(BUILD, { recursive: true, force: true });

    const detailed = report.filter((r) => r.problems.length || r.warnings.length);
    if (detailed.length) {
        console.log('\nDiagnostics:');
        for (const r of detailed) {
            console.log('  ' + r.script);
            r.problems.forEach((p) => console.log('     problem: ' + p));
            r.warnings.forEach((w) => console.log('     warning: ' + w));
            r.unmatched.forEach((u) => console.log('     sql:     ' + u));
        }
    }
    console.log(
        failures
            ? `\n${failures} page(s) had problems.`
            : '\nAll pages rendered from the real PHP templates with no warnings.'
    );
    process.exit(failures ? 1 : 0);
}

function previewIndex(report) {
    const rows = report
        .filter((r) => r.script !== 'superadmin/login.php' && r.outFile)
        .map((r) => {
            const href = 'superadmin/' + r.outFile.replace('.html', '.php');
            return `<a class="pv-card" href="${href}">
            <span class="pv-dot"></span>
            <strong>${r.outFile.replace('.html', '')}</strong>
            <span>${r.bytes.toLocaleString('en-US')} bytes rendered by ${r.script}</span>
        </a>`;
        })
        .join('\n');

    return `<!DOCTYPE html>
<html lang="en" data-theme="dark">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Optibiz Super Admin — preview</title>
    <link rel="stylesheet" href="assets/css/style.css">
    <link rel="stylesheet" href="assets/css/superadmin.css">
    <style>
        .pv-wrap { max-width: 1080px; margin: 0 auto; padding: clamp(28px, 6vw, 72px) 20px 80px; }
        .pv-hero { display: flex; align-items: center; gap: 14px; margin-bottom: 10px; }
        .pv-hero .sa-brand-badge { width: 46px; height: 46px; }
        .pv-hero h1 { font-size: clamp(24px, 4vw, 34px); color: var(--sa-heading); }
        .pv-lede { color: var(--sa-muted); max-width: 70ch; margin: 10px 0 26px; font-size: 14.5px; line-height: 1.7; }
        .pv-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 14px; }
        .pv-card { display: grid; gap: 5px; padding: 18px; border-radius: 16px; border: 1px solid var(--sa-line);
            background: var(--sa-surface); text-decoration: none; color: var(--sa-text);
            transition: transform .18s ease, border-color .18s ease, box-shadow .18s ease; }
        .pv-card:hover { transform: translateY(-3px); border-color: var(--sa-accent-line); box-shadow: var(--sa-shadow); }
        .pv-card strong { color: var(--sa-heading); font-size: 15px; text-transform: capitalize; }
        .pv-card > span:last-child { color: var(--sa-muted); font-size: 12.6px; line-height: 1.5; }
        .pv-dot { width: 9px; height: 9px; border-radius: 50%; background: var(--sa-lime); box-shadow: 0 0 0 4px var(--sa-accent-soft); }
        .pv-toolbar { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 26px; }
        .pv-note { margin-top: 30px; padding: 16px 18px; border-radius: 14px; border: 1px dashed var(--sa-line-strong);
            color: var(--sa-muted); font-size: 13px; line-height: 1.7; }
    </style>
</head>
<body class="sa-body">
<script>
(function () {
    try {
        var t = localStorage.getItem('optibiz-sa-theme');
        if (t === 'light' || t === 'dark') document.documentElement.setAttribute('data-theme', t);
    } catch (e) {}
})();
</script>
<div class="pv-wrap">
    <div class="pv-hero">
        <span class="sa-brand-badge"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg></span>
        <h1>Super admin — rendered preview</h1>
    </div>
    <p class="pv-lede">
        Every page below was produced by <strong>running the real PHP templates</strong>
        (<code>superadmin/*.php</code>, <code>includes/sa_helpers.php</code>, <code>superadmin/_shell.php</code>)
        against a mock database, so what you see is the shipped markup with sample data.
        Point the app at your MySQL database and the same templates render live numbers.
    </p>
    <div class="pv-toolbar">
        <button type="button" class="sa-btn sa-btn-primary" data-sa-theme>Toggle dark / light</button>
        <a class="sa-btn sa-btn-ghost" href="login.php">Login screen</a>
        <a class="sa-btn sa-btn-ghost" href="superadmin/index.php">Open the dashboard</a>
    </div>
    <div class="pv-grid">
${rows}
    </div>
    <p class="pv-note">
        The theme toggle, sidebar collapse, table filtering, column sorting, CSV export and dialogs run from the same
        <code>assets/css/superadmin.css</code> and <code>assets/js/superadmin.js</code> the PHP pages load.
        Forms and buttons that would write to the database are inert in this preview.
    </p>
</div>
<script src="assets/js/superadmin.js"></script>
</body>
</html>
`;
}

main();
